// Generated by adapter-cloudflare, never the application entry.
// @ts-expect-error generated JavaScript has no declaration file
import sveltekit from "./.svelte-kit/cloudflare/_worker.js";
import { canonicalOrigin, createAuth, operatorAllowed } from "./auth.js";
import { handleMcp } from "./mcp.js";
import { boundedBody, equalSecret } from "./security.js";
import { failure } from "./store.js";
import { Telemetry, traceParent } from "./telemetry.js";

export { IssueTracker } from "./store.js";

async function dispatch(
  request: Request,
  env: Env,
  ctx: ExecutionContext,
): Promise<Response> {
  const url = new URL(request.url);
  if (
    url.origin !== canonicalOrigin &&
    url.hostname !== "localhost" &&
    url.hostname !== "127.0.0.1"
  )
    return failure(403);
  const bearer =
    request.headers.get("authorization")?.replace(/^Bearer /, "") ?? "";
  const sameOrigin =
    request.headers.get("origin") === canonicalOrigin ||
    ((url.hostname === "localhost" || url.hostname === "127.0.0.1") &&
      request.headers.get("origin") === url.origin);
  const auth = createAuth(env);
  if (url.pathname === "/mcp") {
    return request.headers.has("origin") && !sameOrigin
      ? failure(403)
      : handleMcp(request, env);
  }
  if (url.pathname.startsWith("/.well-known/oauth-protected-resource")) {
    return Response.json({
      resource: `${canonicalOrigin}/mcp`,
      authorization_servers: [`${canonicalOrigin}/api/auth`],
      scopes_supported: ["issues:read", "issues:write", "traces:read"],
      bearer_methods_supported: ["header"],
    });
  }
  if (
    url.pathname.startsWith("/.well-known/") ||
    url.pathname.startsWith("/api/auth/")
  ) {
    // OAuth token/DCR routes use their own protocol validation. Better Auth owns CSRF for session endpoints.
    if (
      request.method !== "GET" &&
      !url.pathname.startsWith("/api/auth/oauth2/") &&
      !sameOrigin
    )
      return failure(403);
    if (url.pathname === "/.well-known/oauth-authorization-server")
      return auth.handler(
        new Request(
          `${canonicalOrigin}/api/auth/.well-known/oauth-authorization-server`,
          request,
        ),
      );
    return auth.handler(request);
  }
  if (url.pathname === "/api/bootstrap" && request.method === "POST") {
    if (!sameOrigin || !equalSecret(bearer, env.BOOTSTRAP_TOKEN))
      return failure(403);
    if (
      request.headers.get("content-type")?.split(";")[0] !== "application/json"
    )
      return failure(415);
    const input = JSON.parse(await boundedBody(request, 4096));
    if (
      typeof input.email !== "string" ||
      typeof input.password !== "string" ||
      typeof input.name !== "string"
    )
      return failure(400);
    const email = input.email.trim().toLowerCase();
    const claim = await env.AUTH_DB.prepare(
      "SELECT email,completed FROM bootstrap_claim WHERE id=1",
    ).first<{ email: string; completed: number }>();
    if (claim?.completed || (claim && claim.email !== email))
      return failure(409);
    if (!claim) {
      const existing = await env.AUTH_DB.prepare(
        'SELECT count(*) AS n FROM "user"',
      ).first<{ n: number }>();
      if (existing?.n) return failure(409);
      await env.AUTH_DB.prepare(
        "INSERT OR IGNORE INTO bootstrap_claim(id,email) VALUES(1,?)",
      )
        .bind(email)
        .run();
      const locked = await env.AUTH_DB.prepare(
        "SELECT email FROM bootstrap_claim WHERE id=1",
      ).first<{ email: string }>();
      if (locked?.email !== email) return failure(409);
    }
    const existingUser = await env.AUTH_DB.prepare(
      'SELECT id FROM "user" WHERE email=?',
    )
      .bind(email)
      .first<{ id: string }>();
    const result = existingUser
      ? await auth.api.signInEmail({
          body: { email, password: input.password },
        })
      : await createAuth(env, true).api.signUpEmail({
          body: { email, password: input.password, name: input.name },
        });
    await env.AUTH_DB.batch([
      env.AUTH_DB.prepare(
        "INSERT OR IGNORE INTO operator_grants(user_id) VALUES(?)",
      ).bind(result.user.id),
      env.AUTH_DB.prepare(
        "UPDATE bootstrap_claim SET completed=1 WHERE id=1 AND email=?",
      ).bind(email),
    ]);
    return Response.json({ created: true });
  }
  if (url.pathname.startsWith("/api/")) {
    const machine =
      url.pathname === "/api/capture" ||
      url.pathname.startsWith("/api/issue-notices/") ||
      url.pathname.startsWith("/api/migration/");
    const session = machine
      ? null
      : await auth.api.getSession({ headers: request.headers });
    const authorized = Boolean(
      session && (await operatorAllowed(env, session.user.id)),
    );
    if (!machine && !authorized) return failure(401);
    if (!machine && request.method !== "GET" && !sameOrigin)
      return failure(403);
    const forwarded = new Request(request);
    forwarded.headers.delete("x-debug-operator");
    if (!machine && authorized)
      forwarded.headers.set("x-debug-operator", "authorized");
    return env.TRACKER.getByName("operator-tracker-v1").fetch(forwarded);
  }
  return sveltekit.fetch(request, env, ctx);
}

export default {
  async fetch(
    request: Request,
    env: Env,
    ctx: ExecutionContext,
  ): Promise<Response> {
    const telemetry = new Telemetry(env.AXIOM_TELEMETRY_TOKEN);
    const http = telemetry.start(
      "computah.debugshare.http",
      traceParent(request.headers.get("traceparent")),
    );
    const path = new URL(request.url).pathname;
    const operation =
      path === "/mcp"
        ? telemetry.start("computah.debugshare.mcp", http.span)
        : path.startsWith("/api/auth/") || path === "/api/bootstrap"
          ? telemetry.start("computah.debugshare.auth", http.span)
          : undefined;
    const parent = operation?.span ?? http.span;
    const traced = new Request(request);
    traced.headers.set(
      "traceparent",
      `00-${parent.traceId}-${parent.spanId}-01`,
    );
    let response: Response;
    try {
      response = await dispatch(traced, env, ctx);
    } catch {
      response = failure(400);
    }
    const outcome = request.signal.aborted
      ? "cancelled"
      : response.ok || response.status < 400
        ? "success"
        : response.status === 401 || response.status === 403
          ? "denied"
          : "error";
    if (operation) ctx.waitUntil(operation.end(outcome));
    ctx.waitUntil(http.end(outcome));
    const result = new Response(response.body, response);
    result.headers.set("Cache-Control", "no-store");
    result.headers.set("X-Content-Type-Options", "nosniff");
    result.headers.set("Referrer-Policy", "no-referrer");
    result.headers.set("X-Frame-Options", "DENY");
    // SvelteKit supplies nonce/hash CSP for its inline hydration script.
    if (!result.headers.has("Content-Security-Policy"))
      result.headers.set(
        "Content-Security-Policy",
        "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
      );
    return result;
  },
} satisfies ExportedHandler<Env>;
